function useScreen(): [Screen, (s: Screen) => void] {
  const [s, setS] = useState<Screen>("landing");
  useEffect(() => {
    const read = () => {
      const h = window.location.hash.replace("#/", "") as Screen;
      setS(h && h !== ("" as Screen) ? h : "landing");
    };
    read();
    window.addEventListener("hashchange", read);
    return () => window.removeEventListener("hashchange", read);
  }, []);
  const go = (n: Screen) => {
    window.location.hash = n === "landing" ? "" : "/" + n;
    if (n === "landing") setS("landing");
    window.scrollTo({ top: 0 });
  };
  return [s, go];
}

function Index() {
  const [s, go] = useScreen();
  if (s === "landing") return <Landing go={go} />;
  return <AppFrame s={s} go={go} />;
}

function vsrc(k: string): string {
  return "/media/" + k + ".mp4";
}
