function Vw({
  k,
  poster,
  play,
  setPlay,
  style,
  name,
  children,
  demo,
}: {
  k: string;
  poster: string;
  play: string | null;
  setPlay: (v: string | null) => void;
  style?: React.CSSProperties;
  name?: string;
  children?: React.ReactNode;
  demo?: boolean;
}) {
  const ref = useRef<HTMLVideoElement>(null);
  const box = useRef<HTMLDivElement>(null);
  const [src, setSrc] = useState("");
  const [inview, setInview] = useState(false);
  useEffect(() => {
    setSrc(vsrc(k));
  }, [k]);
  useEffect(() => {
    const el = box.current;
    if (!el || !("IntersectionObserver" in window)) {
      setInview(true);
      return;
    }
    const io = new IntersectionObserver((es) => es.forEach((e) => setInview(e.isIntersecting)), {
      threshold: 0.35,
    });
    io.observe(el);
    return () => io.disconnect();
  }, []);
  const on = play === k;
  useEffect(() => {
    const v = ref.current;
    if (!v) return;
    if (on) {
      v.muted = false;
      v.currentTime = 0;
      v.play().catch(() => {});
    } else if (inview) {
      v.muted = true;
      v.play().catch(() => {});
    } else {
      v.pause();
    }
  }, [on, inview, k]);
  const toggle = () => setPlay(on ? null : k);
  return (
    <div
      ref={box}
      className={(demo ? "democard" : "vwin") + (on ? " playing" : "")}
      style={style}
      onClick={toggle}
      role="button"
      tabIndex={0}
      aria-label={(name || "video") + (on ? ", stop" : ", play")}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          toggle();
        }
      }}
    >
      {!demo && (
        <div className="bar glass">
          <i />
          <i />
          <i />
          <span className="btitle">{name}</span>
        </div>
      )}
      {demo && (
        <span
          style={{
            position: "absolute",
            top: 12,
            left: 12,
            zIndex: 3,
            background: "rgba(20,22,28,.8)",
            color: "#fff",
            fontSize: 11.5,
            fontWeight: 600,
            padding: "6px 12px",
            borderRadius: 999,
          }}
        >
          sikshaara instagram reel · @sikshaara_india
        </span>
      )}
      <video
        ref={ref}
        src={src || undefined}
        poster={poster}
        disableRemotePlayback
        muted
        loop
        playsInline
        preload={inview ? "auto" : "metadata"}
      />
      {children}
      {demo && (
        <span className="playpill">
          <svg width="11" height="12" viewBox="0 0 11 12">
            <path d="M1 1.2v9.6L10 6z" fill="#0a0a0a" />
          </svg>
          play video
        </span>
      )}
    </div>
  );
}
const DEPTH: Record<string, number> = { cut: 14, flash: 22, yp1: 32, cost: 26, sik: 36 };
function useReduced(): boolean {
  const [r, setR] = useState(false);
  useEffect(() => {
    const m = window.matchMedia("(prefers-reduced-motion: reduce)");
    setR(m.matches);
    const f = () => setR(m.matches);
    m.addEventListener("change", f);
    return () => m.removeEventListener("change", f);
  }, []);
  return r;
}
function usePointerDepth(ref: React.RefObject<HTMLElement | null>, off: boolean) {
  useEffect(() => {
    const el = ref.current;
    if (!el || off) return;
    let raf = 0;
    let tx = 0;
    let ty = 0;
    let cx = 0;
    let cy = 0;
    const tick = () => {
      cx += (tx - cx) * 0.08;
      cy += (ty - cy) * 0.08;
      el.style.setProperty("--mx", cx.toFixed(3));
      el.style.setProperty("--my", cy.toFixed(3));
      raf = Math.abs(tx - cx) > 0.001 || Math.abs(ty - cy) > 0.001 ? requestAnimationFrame(tick) : 0;
    };
    const move = (e: PointerEvent) => {
      if (e.pointerType !== "mouse") return;
      const r = el.getBoundingClientRect();
      tx = ((e.clientX - r.left) / r.width - 0.5) * 2;
      ty = ((e.clientY - r.top) / r.height - 0.5) * 2;
      if (!raf) raf = requestAnimationFrame(tick);
    };
    const leave = () => {
      tx = 0;
      ty = 0;
      if (!raf) raf = requestAnimationFrame(tick);
    };
    el.addEventListener("pointermove", move);
    el.addEventListener("pointerleave", leave);
    return () => {
      el.removeEventListener("pointermove", move);
      el.removeEventListener("pointerleave", leave);
      cancelAnimationFrame(raf);
    };
  }, [ref, off]);
}
function useReveal(off: boolean) {
  useEffect(() => {
    const els = Array.from(document.querySelectorAll<HTMLElement>("[data-rv]"));
    if (off || !("IntersectionObserver" in window)) {
      els.forEach((e) => e.classList.add("in"));
      return;
    }
    const io = new IntersectionObserver(
      (es) =>
        es.forEach((e) => {
          if (e.isIntersecting) {
            e.target.classList.add("in");
            io.unobserve(e.target);
          }
        }),
      { threshold: 0.2 },
    );
    els.forEach((e) => io.observe(e));
    return () => io.disconnect();
  }, [off]);
}
function Tilt({ className, children }: { className: string; children: React.ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const move = (e: React.PointerEvent) => {
    if (e.pointerType !== "mouse" || !ref.current) return;
    const r = ref.current.getBoundingClientRect();
    ref.current.style.setProperty("--rx", (((e.clientY - r.top) / r.height - 0.5) * -6).toFixed(2) + "deg");
    ref.current.style.setProperty("--ry", (((e.clientX - r.left) / r.width - 0.5) * 8).toFixed(2) + "deg");
  };
  const leave = () => {
    ref.current?.style.setProperty("--rx", "0deg");
    ref.current?.style.setProperty("--ry", "0deg");
  };
  return (
    <div ref={ref} className={className + " tilt"} onPointerMove={move} onPointerLeave={leave}>
      {children}
    </div>
  );
}
function Cal() {
  const [on, setOn] = useState<number[]>([3, 11, 17, 25]);
  const toggle = (n: number) =>
    setOn((o) => (o.includes(n) ? o.filter((d) => d !== n) : [...o, n].sort((a, b) => a - b)));
  return (
    <div className="body">
      <div className="kcal">
        {Array.from({ length: 30 }, (_, i) => i + 1).map((n) => (
          <b
            key={n}
            role="button"
            tabIndex={0}
            onClick={() => toggle(n)}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                toggle(n);
              }
            }}
            className={on.includes(n) ? "hot" : [9, 19, 30].includes(n) ? "warm" : ""}
          >
            {n}
          </b>
        ))}
      </div>
    </div>
  );
}
