function usePersist<T>(key: string, init: T): [T, (v: T | ((o: T) => T)) => void] {
  const [v, setV] = useState<T>(init);
  const [ready, setReady] = useState(false);
  useEffect(() => {
    try {
      const r = window.localStorage.getItem("cd:" + key);
      if (r) {
        const j = JSON.parse(r);
        setV((o) => (Array.isArray(j) || typeof j !== "object" || j === null ? j : { ...o, ...j }) as T);
      }
    } catch {
      /* ignore */
    }
    setReady(true);
  }, [key]);
  useEffect(() => {
    if (ready) {
      try {
        window.localStorage.setItem("cd:" + key, JSON.stringify(v));
      } catch {
        /* ignore */
      }
    }
  }, [key, v, ready]);
  return [v, setV];
}

