type Shared = StudioShared;
type SetFn = (p: Partial<Shared>) => void;

function renderScreen(s: Screen, st: Shared, set: SetFn, go: (s: Screen) => void) {
  switch (s) {
    case "signin":
      return <SignIn go={go} />;
    case "home":
      return <Home st={st} go={go} />;
    case "niche":
      return <Niche st={st} set={set} go={go} />;
    case "platforms":
      return <PlatformsScreen st={st} set={set} go={go} />;
    case "audience":
      return <AudienceScreen st={st} go={go} />;
    case "research":
      return <ResearchScreen st={st} go={go} />;
    case "calendar":
      return <CalendarScreen st={st} set={set} go={go} />;
    case "script":
      return <ScriptScreen st={st} go={go} />;
    case "clips":
      return <ClipsScreen go={go} />;
    case "editor":
      return <VideoEditor st={st} set={set} go={go} />;
    case "publish":
      return <PublishScreen st={st} set={set} />;
    case "insights":
      return <Insights go={go} />;
    case "account":
      return <Account st={st} go={go} />;
    default:
      return <Home st={st} go={go} />;
  }
}

